class BtsCertificatesPage(NavigatablePage):
    """
    As a class will be called by Configuration,
    all operations on BTS Certificates will be implemented under this class.
    """
    _MENU_ROUTE_LIST = ['Configuration', 'Certificate Management', 'BTS Certificates']
    _TA_CERTIFICATES_XPATH = ("//wf-pane[@label='BTS Certificates']//span[text()='TA'] "
                              "| //bts-certificates//td[contains(text(), 'TA')]")
    _CA_CERTIFICATES_XPATH = ("//wf-pane[@label='BTS Certificates']//span[text()='CA'] "
                              "| //bts-certificates//td[contains(text(), 'CA')]")
    _BTS_CERTIFICATES_XPATH = ("//wf-pane[@label='BTS Certificates']//span[text()='BTS'] "
                               "| //bts-certificates//td[contains(text(), 'BTS')]")

    def __init__(self, driver):
        super(BtsCertificatesPage, self).__init__(driver)
        self._view_panel = BtsCertificatesPageViewPanel(driver)
        self._detail_panel = BtsCertificatesPageDetailPanel(driver)

    def _get_detail_panel_info(self, xpath, index=0):
        self._detail_panel.expand_details_panel()
        self._view_panel.show_detail_panel(xpath, index)
        return self._detail_panel.get_certificate_details_info()

    def delete_certificate(self, serial_numbers, timeout=60):
        self._view_panel.delete_certificate(serial_numbers, timeout)

    def get_certificates(self, timeout, cert_type=None, index=0):
        cert_xpath_dict = {'TA': self._TA_CERTIFICATES_XPATH,
                           'CA': self._CA_CERTIFICATES_XPATH,
                           'BTS': self._BTS_CERTIFICATES_XPATH}
        if cert_type:
            cert_xpath_dict = {key: cert_xpath_dict[key] for key in cert_xpath_dict.keys() if key is cert_type}
        cert_dict = {}
        try:
            self._view_panel.expand_certificates_list(timeout)
        except TimeoutException:
            logging.warning("No certificate is found.")
            return cert_dict
        for cert_type, cert_xpath in cert_xpath_dict.items():
            if self._view_panel.element_exists((By.XPATH, cert_xpath)):
                cert_dict[cert_type] = self._get_detail_panel_info(
                    cert_xpath, index)
        return cert_dict

    def get_certificates_number(self, cert_type=None):
        cert_xpath_dict = {'TA': self._TA_CERTIFICATES_XPATH,
                           'CA': self._CA_CERTIFICATES_XPATH,
                           'BTS': self._BTS_CERTIFICATES_XPATH}
        if not cert_type:
            raise Exception('Certificate type does not specified')
        return len(self._view_panel.driver.find_elements_by_xpath(cert_xpath_dict[cert_type]))

    def add_certificate(self, file_path, timeout=60):
        _LOAD_CERTIFICATE_FILE_BUTTON_SCRIPT = (".install-cert-browse-button ui-file-input "
                                                "input[accept='.pem,.der,.crt,.cer']")
        _LOAD_CERTIFICATE_FILE_BUTTON_XPATH = ('//label[contains(text(), "Additional CA certificates")]/..//'
                                               'input[@accept=".pem,.der,.crt,.cer"]')
        _INSTALL_BUTTON_XPATH = "//bts-certificates//button[contains(text(), 'Install')]"
        self._detail_panel.load_file_from_hidden_button(
            _LOAD_CERTIFICATE_FILE_BUTTON_SCRIPT,
            _LOAD_CERTIFICATE_FILE_BUTTON_XPATH,
            file_path, timeout)
        self._view_panel.wait_for_text_not_present_in_element((
            By.XPATH, _INSTALL_BUTTON_XPATH), 'disabled', timeout=10)
        self._detail_panel.click_enabled_element((
            By.XPATH, _INSTALL_BUTTON_XPATH))

    def install_bts_certificates_from_local(self, bts_file_path, password, additional_ca_file_path, timeout):
        """
        Keyword for install certificates from local in BTS Certificates page
        :param bts_file_path: file, bts certificates file
        :param password: str, password for install certificates
        :param additional_ca_file_path: file, additional certificates file
        :param timeout: int, time to wait file load, default is 60 second
        :return: str, result of install certificates
        """
        return self._view_panel.install_bts_certificates_from_local(bts_file_path,
                                                                    password,
                                                                    additional_ca_file_path,
                                                                    timeout)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


class BtsCertificatesPageNavigationPanel(NavigationPanel):
    pass


class BtsCertificatesPageViewPanel(ViewPanel):
    _EXPAND_CERTIFICATES_XPATH = ("//bts-certificates//button[@aria-label='Expand all'] "
                                  "| //bts-certificates//p-button[@title='Expand all']")
    _BTS_TRUST_CHAIN_HIDDEN_BUTTON_SCRIPT = ("div[class='install-cert-row'] ui-file-input"
                                             "[a-accept-type='.p12'] input[type='file']")
    _ADDITIONAL_CA_CERTIFICATES_HIDDEN_BUTTON_SCRIPT = ("div[class='install-cert-row'] ui-file-input"
                                                        "[a-accept-type='.pem,.der,.crt,.cer'] input[type='file']")
    _BTS_TRUST_CHAIN_BUTTON_XPATH = "//*[text()=' Browse...']/../../input[@type='file'][@accept='.p12']"
    _ADDITIONAL_CA_CERTIFICATES_BUTTON_XPATH = ("//*[text()=' Browse...']/../../input[@type='file']"
                                                "[@accept='.pem,.der,.crt,.cer']")
    _BTS_TRUST_CHAIN_PASSWORD_INPUT_XPATH = "//input[@id='chainPwd']"
    _INSTALL_BUTTON_XPATH = "//button[text()=' Install']"
    _INSTALL_CERTIFICATES_INFO_SUCCESS_XPATH = ("//div[@class='wf-inlineinfo-container']"
                                                "/span[contains(@class, 'icon-ok')]")
    _INSTALL_CERTIFICATES_INFO_SUCCESS_TEXT = "Certificates installation completed"
    _INSTALL_CERTIFICATES_INFO_ERROR_XPATH = ("//div[@class='install-status-group']/div"
                                              "/span[contains(@class, 'install-cert-error-msg')]")
    _CERTIFICATE_CHOOSE_XPATH = '//bts-certificates//tr[td//span[contains(text(), "{}")]]/td[1]//label'
    _DELETE_BUTTON_XPATH = '//bts-certificates-delete//button'
    _DELETE_COMPLETED_INFO = '//bts-certificates-delete//*[contains(text(), "Certificates deletion completed")]'

    def __init__(self, driver):
        super(BtsCertificatesPageViewPanel, self).__init__(driver)

    def expand_certificates_list(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._EXPAND_CERTIFICATES_XPATH), timeout)

    def install_bts_certificates_from_local(self, bts_file_path, password, additional_ca_file_path, timeout):
        try:
            if bts_file_path:
                self.load_file_from_hidden_button(self._BTS_TRUST_CHAIN_HIDDEN_BUTTON_SCRIPT,
                                                  self._BTS_TRUST_CHAIN_BUTTON_XPATH, bts_file_path, timeout)
                self.insert_text_to_enable_element((By.XPATH, self._BTS_TRUST_CHAIN_PASSWORD_INPUT_XPATH), password,
                                                   timeout)
            if additional_ca_file_path:
                self.load_file_from_hidden_button(self._ADDITIONAL_CA_CERTIFICATES_HIDDEN_BUTTON_SCRIPT,
                                                  self._ADDITIONAL_CA_CERTIFICATES_BUTTON_XPATH,
                                                  additional_ca_file_path, timeout)
            self.click_enabled_element((By.XPATH, self._INSTALL_BUTTON_XPATH), timeout)
            self.wait_for_visibility_by_xpath(self._INSTALL_CERTIFICATES_INFO_SUCCESS_XPATH, timeout)
            return self._INSTALL_CERTIFICATES_INFO_SUCCESS_TEXT
        except TimeoutException:
            error_text = self.get_text_by_xpath(self._INSTALL_CERTIFICATES_INFO_ERROR_XPATH)
            if error_text:
                return error_text

    def delete_certificate(self, serial_numbers, timeout=60):
        if not isinstance(serial_numbers, list):
            raise AttributeError('The param serial_numbers should be type of list.')

        for serial_number in serial_numbers:
            self.click_element_by_xpath(self._CERTIFICATE_CHOOSE_XPATH.format(serial_number))
        self.click_element_by_xpath(self._DELETE_BUTTON_XPATH)

        delete_certificate_modal = DeleteCertificateModal(self.driver)
        delete_certificate_modal.wait_for_delete_certificate_modal_appear(timeout)
        delete_certificate_modal.delete(timeout)

        self.wait_for_visibility_by_xpath(self._DELETE_COMPLETED_INFO)


class BtsCertificatesPageDetailPanel(DetailPanel):
    _DETAILS_KEY_XPATH = "//certificate-details//tr[count(*)=2]/th"
    _DETAILS_VALUE_XPATH = "//certificate-details//tr[count(*)=2]/td"

    def __init__(self, driver):
        super(BtsCertificatesPageDetailPanel, self).__init__(driver)

    def get_certificate_details_info(self):
        """
        Get certificate details info on the details panel.
        :return: dict
        """
        return self.get_dict_from_elements_by_xpath(self._DETAILS_KEY_XPATH, self._DETAILS_VALUE_XPATH, ':')


class AutomaticManagementPage(NavigatablePage):
    """
    As a class will be called by Configuration,
    all operations on Automatic Management will be implemented under this class.
    """
    _MENU_ROUTE_LIST = ['Configuration', 'Certificate Management', 'Automatic Management']

    def __init__(self, driver):
        super(AutomaticManagementPage, self).__init__(driver)
        self._view_panel = AutomaticManagementPageViewPanel(driver)

    def update_cmp_server_settings(self, reference_number, pre_shared_key):
        return self._view_panel.update_cmp_server_settings(reference_number, pre_shared_key)

    def initialize_certificates(self):
        return self._view_panel.initialize_certificates()

    def get_cmp_state(self, timeout):
        return self._view_panel.get_cmp_state(timeout)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


class AutomaticManagementPageNavigationPanel(NavigationPanel):
    pass


class AutomaticManagementPageViewPanel(ViewPanel):
    _REFERENCE_NUMBER_XPATH = "refNumber"
    _PRE_SHARED_KEY_XPATH = "psKey"
    _UPDATE_CMP_SERVER_BUTTON_XPATH = "//div[@class='cmp-update']//button"
    _UPDATE_CMP_SERVER_STATUS_XPATH = "//div[@class='cmp-update']//span[contains(@class,'icon')]"
    _INITIALIZE_CERTIFICATES_BUTTON_XPATH = "//ui-button[@a-text='Initialize Certificates']/button"
    _INITIALIZE_CERTIFICATES_STATUS_XPATH = ("//ui-button[@a-text='Initialize Certificates']/following-sibling::div"
                                             "//span[contains(@class,'icon')]")
    CMP_STATE_XPATH = '//*[@class="cmp-state"]/span'

    def __init__(self, driver):
        super(AutomaticManagementPageViewPanel, self).__init__(driver)

    def update_cmp_server_settings(self, reference_number, pre_shared_key):
        """
        Update CMP server settings at Automatic Management tab.
        :param reference_number: str, reference number
        :param pre_shared_key: str, per-shared key
        :return: boolean, True if succeed
        """
        filter_attribute = 'class'
        filter_attribute_text = 'icon-ok'

        self.insert_text_to_enabled_element((By.ID, self._REFERENCE_NUMBER_XPATH), reference_number, 5)
        self.insert_text_to_enabled_element((By.ID, self._PRE_SHARED_KEY_XPATH), pre_shared_key, 5)
        self.click_enabled_element((By.XPATH, self._UPDATE_CMP_SERVER_BUTTON_XPATH))
        self.wait_for_text_present_in_attribute(self._UPDATE_CMP_SERVER_STATUS_XPATH,
                                                filter_attribute, filter_attribute_text)

        update_cmp_server_status = self.get_attribute_by_xpath(self._UPDATE_CMP_SERVER_STATUS_XPATH, filter_attribute)
        return "ok" in update_cmp_server_status

    def initialize_certificates(self):
        """
        Initialize certificates at Automatic Management tab.
        :return: str, certificates initialized status
        """
        filter_attribute = 'class'
        filter_attribute_text = 'icon-ok'

        self.click_enabled_element((By.XPATH, self._INITIALIZE_CERTIFICATES_BUTTON_XPATH), 5)
        initialize_certificates_modal = InitializeCertificatesModal(self.driver)
        initialize_certificates_modal.wait_until_initialize_certificates_modal_appear()
        initialize_certificates_modal.initialize()
        self.wait_for_text_present_in_attribute(self._INITIALIZE_CERTIFICATES_STATUS_XPATH,
                                                filter_attribute,
                                                filter_attribute_text)

        initialize_certificates_status = self.get_attribute_by_xpath(self._INITIALIZE_CERTIFICATES_STATUS_XPATH,
                                                                     filter_attribute)
        return "ok" in initialize_certificates_status

    def get_cmp_state(self, timeout):
        """
        Get CMP state
        """
        return self.get_text_by_xpath(self.CMP_STATE_XPATH, timeout)


