class VendorCertificatesPage(NavigatablePage):
    """
    As a class will be called by Configuration,
    all operations on Vendor Certificates will be implemented under this class.
    """
    _MENU_ROUTE_LIST = ['Configuration', 'Certificate Management', 'Vendor Certificates']
    _TA_CERTIFICATES_XPATH = "//wf-pane[@label='Vendor Certificates']//span[text()='TA']"
    _CA_CERTIFICATES_XPATH = "//wf-pane[@label='Vendor Certificates']//span[text()='CA']"
    _Vendor_CERTIFICATES_XPATH = "//wf-pane[@label='Vendor Certificates']//span[text()='Vendor']"

    def __init__(self, driver):
        super(VendorCertificatesPage, self).__init__(driver)
        self._view_panel = VendorCertificatesPageViewPanel(driver)
        self._detail_panel = VendorCertificatesPageDetailPanel(driver)

    def _get_detail_panel_info_vendor(self, xpath):
        self._detail_panel.expand_details_panel()
        self._view_panel.show_detail_panel(xpath)
        return self._detail_panel.get_certificate_details_info_vendor()

    def get_certificates_vendor(self, timeout):
        cert_xpath_dict = {'TA': self._TA_CERTIFICATES_XPATH,
                           'CA': self._CA_CERTIFICATES_XPATH,
                           'Vendor': self._Vendor_CERTIFICATES_XPATH}
        cert_dict = {}
        try:
            self._view_panel.expand_certificates_list_vendor(timeout)
        except TimeoutException:
            logging.warning("No certificate is found.")
            return cert_dict
        for cert_type, cert_xpath in cert_xpath_dict.items():
            if self._view_panel.element_exists((By.XPATH, cert_xpath)):
                cert_dict[cert_type] = self._get_detail_panel_info_vendor(cert_xpath)
        return cert_dict

    def restore_vendor_certificates(self, timeout_for_restore):
        return self._view_panel.restore_vendor_certificates(timeout_for_restore)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


class VendorCertificatesPageNavigationPanel(NavigationPanel):
    pass


class VendorCertificatesPageViewPanel(ViewPanel):
    _EXPAND_CERTIFICATES_XPATH = "//vendor-certificates//button[@aria-label='Expand all']"
    _RESTORE_VENDOR_CERTIFICATES_XPATH = ("//wf-pane[@label='Vendor Certificates']"
                                          "//button[normalize-space(text())='Restore Vendor Certificates']")
    _RESTORE_VENDOR_CERTIFICATES_RESULT_XPATH = "//*[@class='restore-vendor-certificates']/wf-inlineinfo"
    _RESTORE_VENDOR_CERTIFICATES_ON_PROCESS_XPATH = ("//*[@class='restore-vendor-certificates']"
                                                     "//span[@class='icon spinner']")

    def __init__(self, driver):
        super(VendorCertificatesPageViewPanel, self).__init__(driver)

    def expand_certificates_list_vendor(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._EXPAND_CERTIFICATES_XPATH), timeout)

    def restore_vendor_certificates(self, timeout_for_restore):
        self.wait_for_visibility_by_xpath(self._RESTORE_VENDOR_CERTIFICATES_XPATH, timeout=timeout_for_restore)
        self.click_enabled_element((By.XPATH, self._RESTORE_VENDOR_CERTIFICATES_XPATH), timeout=timeout_for_restore)
        restore_vendor_modal = RestoreVendorCertificateModal(self.driver)
        restore_vendor_modal.wait_for_restore_vendor_certificates_modal_appear(timeout_for_restore)
        restore_vendor_modal.restore(timeout=timeout_for_restore)
        self.wait_until_element_is_invisible(self._RESTORE_VENDOR_CERTIFICATES_ON_PROCESS_XPATH,
                                             timeout=timeout_for_restore)
        return self.get_text_by_xpath(self._RESTORE_VENDOR_CERTIFICATES_RESULT_XPATH, timeout=timeout_for_restore)


